create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,full_name text not null default '',plan text not null default 'free' check(plan in ('free','pro')),credits integer not null default 10 check(credits>=0),created_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,description text not null default '',tech_stack jsonb not null default '{}'::jsonb,roadmap jsonb not null default '{}'::jsonb,master_prompt text not null default '',created_at timestamptz not null default now(),constraint projects_id_user_id_unique unique(id,user_id));
create table if not exists public.security_audits(id uuid primary key default gen_random_uuid(),project_id uuid,user_id uuid not null references public.profiles(id) on delete cascade,code_snippet text not null,vulnerabilities_found jsonb not null default '[]'::jsonb,fix_prompt text not null default '',risk_score text not null default 'MEDIUM' check(risk_score in ('CRITICAL','HIGH','MEDIUM','LOW','SAFE')),created_at timestamptz not null default now(),constraint security_audits_project_owner_fk foreign key(project_id,user_id) references public.projects(id,user_id) on delete set null (project_id));
create index if not exists projects_user_created_idx on public.projects(user_id,created_at desc);create index if not exists audits_user_created_idx on public.security_audits(user_id,created_at desc);
alter table public.profiles enable row level security;alter table public.projects enable row level security;alter table public.security_audits enable row level security;
drop policy if exists "profile owner can read" on public.profiles;create policy "profile owner can read" on public.profiles for select to authenticated using((select auth.uid())=id);
drop policy if exists "project owner can read" on public.projects;create policy "project owner can read" on public.projects for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "project owner can insert" on public.projects;create policy "project owner can insert" on public.projects for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists "project owner can update" on public.projects;create policy "project owner can update" on public.projects for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "project owner can delete" on public.projects;create policy "project owner can delete" on public.projects for delete to authenticated using((select auth.uid())=user_id);
drop policy if exists "audit owner can read" on public.security_audits;create policy "audit owner can read" on public.security_audits for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "audit owner can insert" on public.security_audits;create policy "audit owner can insert" on public.security_audits for insert to authenticated with check((select auth.uid())=user_id and (project_id is null or exists(select 1 from public.projects p where p.id=project_id and p.user_id=(select auth.uid()))));
create or replace function public.blui_handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,email,full_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do update set email=excluded.email;return new;end;$$;
revoke all on function public.blui_handle_new_user() from public,anon,authenticated;drop trigger if exists blui_on_auth_user_created on auth.users;create trigger blui_on_auth_user_created after insert on auth.users for each row execute function public.blui_handle_new_user();
create or replace function public.consume_blui_credit(p_user_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare changed_id uuid;begin if (select auth.uid()) is null or (select auth.uid())<>p_user_id then raise exception 'not authorized';end if;update public.profiles set credits=credits-1 where id=p_user_id and credits>0 returning id into changed_id;return changed_id is not null;end;$$;
revoke all on function public.consume_blui_credit(uuid) from public,anon;grant execute on function public.consume_blui_credit(uuid) to authenticated;
grant select on public.profiles to authenticated;grant select,insert,update,delete on public.projects to authenticated;grant select,insert on public.security_audits to authenticated;
